from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th positive integer divisible by at least one denomination."""
    useful = sorted(set(coins))
    filtered = []
    for c in useful:
        if not any(c % d == 0 for d in filtered):
            filtered.append(c)

    high = min(filtered) * k
    cap = high + 1
    # Each subset contributes +1 for odd size and -1 for even size.
    lcms = [1]
    signs = [-1]
    for c in filtered:
        old_len = len(lcms)
        for i in range(old_len):
            new_lcm = lcms[i] // gcd(lcms[i], c) * c
            lcms.append(min(new_lcm, cap))
            signs.append(-signs[i])

    def count(x: int) -> int:
        total = 0
        for lcm, sign in zip(lcms[1:], signs[1:]):
            if lcm <= x:
                total += sign * (x // lcm)
        return total

    low = 1
    while low < high:
        mid = (low + high) // 2
        if count(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low"}
